gunModels['blaster-kit.png']='data:image/png;base64,';
async function installProps(special, knife, bench, obstacles) {
  async function load(name,kit) {
    const manager=new THREE.LoadingManager();
    manager.setURLModifier(url=>url.endsWith('colormap.png')?gunModels[kit+'.png']:url);
    const bytes=Uint8Array.from(atob(gunModels[name+'.glb']),c=>c.charCodeAt(0));
    const loader=new THREE.GLTFLoader(manager);
    const gltf=await new Promise((resolve,reject)=>loader.parse(bytes.buffer,'',resolve,reject));
    return gltf.scene;
  }

  async function replace(group,name,kit,length,angle) {
    const model=await load(name,kit);
    model.rotation.x=angle;
    const box=new THREE.Box3().setFromObject(model), size=box.getSize(new THREE.Vector3());
    const scale=length/Math.max(size.x,size.y,size.z);
    model.scale.setScalar(scale);
    model.position.copy(box.getCenter(new THREE.Vector3())).multiplyScalar(-scale);
    model.position.z=(group.userData.flash?.position.z ?? -.26)+size.z*scale/2;
    for(const part of [...group.children])if(part.isMesh && part!==group.userData.flash)group.remove(part);
    group.add(model);
  }
  await Promise.all([
    replace(special.sp_gatling,'blaster-n','blaster-kit',1,0),
    replace(special.sp_rocket,'blaster-a','blaster-kit',.9,0),
    replace(special.sp_a2g,'blaster-r','blaster-kit',.34,0),
    replace(knife,'tool-axe','survival-kit',.42,-1.0)
  ]);
  const table=await load('workbench','survival-kit');
  table.scale.set(9,5,5);bench.children.filter(c=>c.isMesh).forEach(c=>c.visible=false);bench.add(table);
  const crate=await load('box-large','survival-kit');
  for(const {mesh} of obstacles){
    if(![18,-20,-28].includes(mesh.position.z) || ![-12,15,0].includes(mesh.position.x))continue;
    const {width,height,depth}=mesh.geometry.parameters;
    const prop=crate.clone();prop.scale.set(width/.25,height/.25,depth/.5);
    prop.position.copy(mesh.position);prop.position.y-=height/2;mesh.visible=false;mesh.parent.add(prop);
  }
}

